echo "===KERNEL/OS==="; uname -a; ls -la /boot/firmware/kernel*.img 2>/dev/null | head -4; cat /etc/rpi-issue 2>/dev/null; ls -la --time-style=long-iso /etc/hostname /home/pi/.bash_logout
echo "===BT_FIRMWARE==="; dpkg -l | grep -iE "bluez|firmware-brcm|pi-bluetooth|pipewire |wireplumber|libspa-0.2-bluetooth" | awk '{print $2, $3}'; ls -la --time-style=long-iso /lib/firmware/brcm/BCM4345C0.hcd /lib/firmware/brcm/BCM4345C0.raspberrypi,5-model-b.hcd /usr/lib/firmware/brcm/BCM4345C0*.hcd 2>/dev/null; md5sum /lib/firmware/brcm/BCM4345C0*.hcd 2>/dev/null; strings /lib/firmware/brcm/BCM4345C0.hcd 2>/dev/null | grep -iE "BCM4345C0|version" | head -3
echo "===DMESG_BT==="; sudo -n dmesg 2>/dev/null | grep -iE "hci0|bcm|bluetooth" | head -15
echo "===HCI_VERSION==="; hciconfig -a hci0 | grep -E "HCI Ver|LMP Ver|Manufacturer"; sudo -n btmgmt info 2>/dev/null | grep -iE "version|manufacturer|supported settings"
echo "===ESCO_PARAMS==="; cat /sys/module/bluetooth/parameters/disable_esco 2>/dev/null; cat /sys/module/bluetooth/parameters/enable_ecred 2>/dev/null; ls /sys/module/bluetooth/parameters/
echo "===UART_DT==="; for d in /proc/device-tree/soc/serial@7e201000 /proc/device-tree/axi/pcie@*/rp1/serial@* /proc/device-tree/soc/serial@7d001000; do [ -d "$d" ] && echo "$d: status=$(tr -d '\0' < $d/status 2>/dev/null) bt=$(ls $d 2>/dev/null | grep -i blue)"; done; find /proc/device-tree -maxdepth 4 -name "bluetooth*" 2>/dev/null | head; for b in $(find /proc/device-tree -maxdepth 5 -name "bluetooth*" -type d 2>/dev/null); do echo "$b max-speed=$(od -An -tu4 --endian=big $b/max-speed 2>/dev/null) compatible=$(tr -d '\0' < $b/compatible)"; done
echo "===PIPEWIRE==="; pipewire --version | head -2; wireplumber --version 2>/dev/null | head -1; grep -rhE "bluez5\.(enable-msbc|hfphsp-backend|roles|msbc-force-mtu|hw-offload|codecs)" /usr/share/wireplumber/ /etc/wireplumber/ ~/.config/wireplumber/ 2>/dev/null | sort -u | head
echo "===BT_SCO_SETTINGS (hci)==="; sudo -n hcitool cmd 0x03 0x0025 2>/dev/null | tail -2   # Read Voice Setting
echo "===APT_UPGRADABLE==="; apt list --upgradable 2>/dev/null | grep -iE "bluez|firmware|pipewire|wireplumber|linux-image|raspi" | head
echo "===PREV_KERNEL_LOGS==="; journalctl --list-boots --no-pager 2>/dev/null | tail -5; for b in -1 -2; do echo "boot $b: $(journalctl -b $b -k --no-pager 2>/dev/null | grep -m1 -oE 'Linux version [^ ]+') decode_failed=$(journalctl -b $b --no-pager 2>/dev/null | grep -c 'decode failed')"; done
